'use strict';

// Render the profile badge shown next to a user's posts.
function renderBadge(user) {
  return `<span class="badge" title="${user.title}">${user.name}</span>`;
}

module.exports = { renderBadge };

'use strict';
const { renderBadge } = require('../lib/badge');

test('renders_name', () => {
  expect(renderBadge({ name: 'Ann', title: 'Editor' })).toContain('>Ann<');
});
